<?php

declare(strict_types=1);

namespace Domain\Chat\Api;

use App\Contracts\Domains\ApiSender;
use App\Support\CallKey;
use Domain\Chat\Data\DockAnswerData;
use Domain\Chat\Data\DockListData;
use Domain\Chat\Support\DockProjection;

/**
 * The API of Chat, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class ChatApi
{
    public function __construct(private ApiSender $sender) {}

    public function dockAdd(
        string $type,
        string $id,
        string|null $chat,
        CallKey $requestKey = new CallKey(),
    ): DockAnswerData {
        return $this->sender->send(DockAddPayload::from([
            'type' => $type,
            'id' => $id,
            'chat' => $chat,
            'requestKey' => $requestKey,
        ]));
    }

    public function dockList(
        int $limit = DockProjection::LARGEST_CARD_LIMIT,
        string|null $chat = null,
    ): DockListData {
        return $this->sender->send(DockListPayload::from([
            'limit' => $limit,
            'chat' => $chat,
        ]));
    }

    public function dockRemove(
        string $placement,
        string|null $chat,
        CallKey $requestKey = new CallKey(),
    ): DockAnswerData {
        return $this->sender->send(DockRemovePayload::from([
            'placement' => $placement,
            'chat' => $chat,
            'requestKey' => $requestKey,
        ]));
    }
}
